import java.util.*;
import java.io.*;

public class MinCostFlow {
    static final int N = 100010;
    static final int M = 1000010;
    static final int inf = 1000000000;
    static final int winf = 1000000000;

    static class Road {
        int nxt, to, f;
        long w;

        Road(int nxt, int to, int f, long w) {
            this.nxt = nxt;
            this.to = to;
            this.f = f;
            this.w = w;
        }
    }

    static Road[] r = new Road[M << 1];
    static int[] head = new int[N];
    static int cnt = 1, all;
    static int[] g[] = new int[N];
    static int n, m, k, c, d;
    static int ss = 1, tt = 2;
    static int maxf;
    static long minw;
    static int[] cur = new int[N];
    static boolean[] vis = new boolean[N];
    static long[] dis = new long[N];
    static long[] tag = new long[N];

    static class Node implements Comparable<Node> {
        int u;
        long v;

        Node(int u, long v) {
            this.u = u;
            this.v = v;
        }

        public int compareTo(Node a) {
            return Long.compare(a.v, this.v);
        }
    }

    static PriorityQueue<Node> q = new PriorityQueue<>();

    static void add(int u, int v, int f, long w) {
        r[++cnt] = new Road(head[u], v, f, w);
        head[u] = cnt;
        r[++cnt] = new Road(head[v], u, 0, -w);
        head[v] = cnt;
    }

    static boolean dij(int s, int t) {
        for (int i = 1; i <= all; i++) {
            dis[i] = winf;
            cur[i] = head[i];
            vis[i] = false;
        }
        dis[t] = 0;
        q.clear();
        q.offer(new Node(t, 0));
        while (!q.isEmpty()) {
            int u = q.peek().u;
            q.poll();
            if (vis[u]) continue;
            vis[u] = true;
            for (int i = head[u]; i != 0; i = r[i].nxt) {
                int v = r[i].to;
                long w = tag[u] + r[i ^ 1].w - tag[v];
                if (r[i ^ 1].f > 0 && dis[u] + w < dis[v]) {
                    dis[v] = dis[u] + w;
                    q.offer(new Node(v, dis[v]));
                }
            }
        }
        for (int i = 1; i <= all; i++) {
            tag[i] = Math.min(tag[i] + dis[i], (long) winf);
        }
        if (!vis[s]) return false;
        Arrays.fill(vis, false);
        return true;
    }

    static int dfs(int u, int t, int fl) {
        if (u == t || fl == 0) return fl;
        int res = 0;
        vis[u] = true;
        for (int i = cur[u]; i != 0; i = r[i].nxt) {
            if (r[i].f > 0) {
                int v = r[i].to;
                int f;
                if (!vis[v] && tag[v] + r[i].w == tag[u] && (f = dfs(v, t, Math.min(fl, r[i].f))) > 0) {
                    r[i].f -= f;
                    r[i ^ 1].f += f;
                    res += f;
                    fl -= f;
                    if (fl == 0) break;
                }
            }
        }
        vis[u] = false;
        return res;
    }

    static void work(int t) {
        all += n;
        for (int u = 1; u <= n; u++) {
            for (int v : g[u]) {
                for (int p = 1; p <= k; p++) {
                    add(id(t, u), id(t + 1, v), 1, d * (2 * p - 1));
                }
            }
        }
        for (int u = 1; u <= n; u++) {
            add(id(t, u), id(t + 1, u), inf, 0);
        }
        add(id(t + 1, 1), tt, inf, c * (t + 1));
    }

    static int id(int t, int x) {
        return t * n + x + 2;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());
        k = Integer.parseInt(st.nextToken());
        c = Integer.parseInt(st.nextToken());
        d = Integer.parseInt(st.nextToken());
        all = n + 2;

        for (int i = 0; i < N; i++) {
            g[i] = new int[0];
        }

        for (int i = 1; i <= k; i++) {
            int a = Integer.parseInt(br.readLine());
            add(ss, id(0, a), 1, 0);
        }

        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken());
            int v = Integer.parseInt(st.nextToken());
            g[u] = Arrays.copyOf(g[u], g[u].length + 1);
            g[u][g[u].length - 1] = v;
            g[v] = Arrays.copyOf(g[v], g[v].length + 1);
            g[v][g[v].length - 1] = u;
        }

        add(id(0, 1), tt, inf, 0);
        for (int i = 0; i <= n + k; i++) {
            work(i);
        }
        min_cost_flow_work(ss, tt);
        System.out.println(minw);
    }

    static void min_cost_flow_work(int s, int t) {
        while (dij(s, t)) {
            int w = dfs(s, t, inf);
            maxf += w;
            minw += (long) w * tag[s];
        }
    }
}
